// ⚙️ CAMBIÁ ESTOS VALORES ------------------------------------------
const CONFIG = {
  // El mismo texto que pusiste en privado.config_n8n (secreto)
  secreto: 'una-frase-larga-y-secreta',
  // Project URL de Supabase (Project Settings → Data API), sin barra al final
  supabase_url: 'https://TU-PROYECTO.supabase.co',
  // Modelo de Gemini (cambialo si Google lo renombra)
  modelo_gemini: 'gemini-3.5-flash',
  // No repetir la alerta del mismo producto antes de estas horas
  horas_entre_alertas: 12,
};
// ------------------------------------------------------------------

const entrada = $input.first().json;
const headers = entrada.headers || {};
if ((headers['x-webhook-secret'] || '') !== CONFIG.secreto) {
  // Alguien que no es tu Supabase intentó llamar al webhook
  throw new Error('Aviso rechazado: el secreto no coincide');
}
return [{ json: { ...(entrada.body || {}), config: CONFIG } }];

const d = $input.first().json;
const p = d.record || {};
const stock = Number(p.stock);
const minimo = Number(p.stock_minimo);

// Sin mínimo configurado, o stock por encima: no hay nada que avisar
if (!(minimo > 0) || stock > minimo) return [];

// Si ya avisamos hace poco, no molestamos (salvo que se haya agotado)
if (p.ultima_alerta && stock > 0) {
  const horas = (Date.now() - new Date(p.ultima_alerta).getTime()) / 36e5;
  if (horas < d.config.horas_entre_alertas) return [];
}
return [{ json: { producto_id: p.id, stock, minimo } }];

const c = $input.first().json;
const p = c.producto;
const negocio = (c.negocio && c.negocio.nombre_negocio) || 'un pequeño comercio';

const prompt = `Sos asesor de compras de ${negocio}, un emprendimiento en Santa Cruz, Bolivia.
Un producto llegó a su stock mínimo. Datos:
- Producto: ${p.nombre} (se vende por ${p.unidad})
- Stock actual: ${p.stock} · Stock mínimo: ${p.stock_minimo}
- Costo actual: ${p.costo} Bs · Precio de venta: ${p.precio_venta} Bs
- Vendido en los últimos 7 días: ${c.vendido_7_dias} · en 30 días: ${c.vendido_30_dias}
- Ventas por día (30 días): ${JSON.stringify(c.ventas_por_dia)}
- Últimos costos de compra: ${JSON.stringify(c.costos_recientes)}

Respondé en español, en 3 o 4 líneas cortas, sin markdown:
1) Cuántas unidades conviene reponer (un número concreto, para cubrir unas 2 semanas más el mínimo).
2) Para cuándo, según el ritmo de venta.
3) Si los costos subieron o bajaron, decilo y sugerí si ajustar el precio.`;

return [{ json: { gemini_body: {
  contents: [{ role: 'user', parts: [{ text: prompt }] }],
  generationConfig: { temperature: 0.3 }
} } }];

const g = $input.first().json;
const partes = (g.candidates && g.candidates[0] && g.candidates[0].content && g.candidates[0].content.parts) || [];
const consejo = partes.filter(x => !x.thought).map(x => x.text || '').join('').trim()
  || 'Gemini no devolvió una recomendación esta vez.';

const c = $('Datos del producto').first().json;
const p = c.producto;
const n = c.negocio || {};

const mensaje = `⚠️ Stock bajo: ${p.nombre}
Quedan ${p.stock} ${p.unidad} (mínimo ${p.stock_minimo}).

💡 Recomendación:
${consejo}`;

return [{ json: {
  producto_id: p.id,
  chat_id: n.telegram_chat_id || '',
  email: n.email || '',
  asunto: `Stock bajo: ${p.nombre}`,
  mensaje
} }];

const c = $('Datos de la compra').first().json;
const lista = (c.productos || [])
  .map(p => `- id ${p.id}: ${p.nombre} (${p.unidad}, costo actual ${p.costo} Bs)`)
  .join('\n') || '(todavía no hay productos cargados)';

const prompt = `Leé esta nota de compra de un comercio de Santa Cruz, Bolivia (montos en bolivianos).
Texto escrito por la persona: ${c.compra.texto || '(sin texto: leé la foto)'}

Productos que vende el negocio:
${lista}

Extraé cada producto comprado. Para cada uno:
- producto_id: el id de la lista que corresponde (ej. "coca 2L" = "Coca-Cola 2 litros"); null si no está en la lista.
- nombre: como aparece en la nota.
- cantidad: unidades compradas, en la misma unidad que usa el negocio (si compró "1 paquete de 6", son 6).
- costo_unitario: precio por UNA unidad. Si la nota da el total, dividilo por la cantidad.
Respondé sólo con JSON: {"items":[{"producto_id":1,"nombre":"...","cantidad":0,"costo_unitario":0}]}`;

const parts = [{ text: prompt }];
const item = $input.first();
if (item.binary && item.binary.data) {
  const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
  parts.push({ inlineData: {
    mimeType: item.binary.data.mimeType || 'image/jpeg',
    data: buffer.toString('base64')
  } });
}

return [{ json: { gemini_body: {
  contents: [{ role: 'user', parts }],
  generationConfig: { temperature: 0.1, responseMimeType: 'application/json' }
} } }];

const g = $input.first().json;
const partes = (g.candidates && g.candidates[0] && g.candidates[0].content && g.candidates[0].content.parts) || [];
const texto = partes.filter(x => !x.thought).map(x => x.text || '').join('').replace(/```json|```/g, '').trim();
const compra_id = $('Datos de la compra').first().json.compra.id;

// Convierte "8,50 Bs" → 8.5
const numero = v => {
  if (v === null || v === undefined || v === '') return null;
  const n = Number(String(v).replace(',', '.').replace(/[^0-9.\-]/g, ''));
  return Number.isFinite(n) ? n : null;
};

try {
  const j = JSON.parse(texto);
  const items = (Array.isArray(j) ? j : (j.items || [])).map(i => ({
    producto_id: i.producto_id ? Number(i.producto_id) : null,
    nombre: String(i.nombre || ''),
    cantidad: numero(i.cantidad),
    costo_unitario: numero(i.costo_unitario)
  }));
  return [{ json: { compra_id, entendido: items.length > 0, items, detalle: texto } }];
} catch (e) {
  return [{ json: { compra_id, entendido: false, items: [], detalle: texto || 'Respuesta vacía' } }];
}

const r = $input.first().json;
if (r.ya_procesada) return [];

const c = $('Datos de la compra').first().json;
const n = c.negocio || {};
const lineas = (r.cambios || []).map(x => {
  let costo = '';
  if (x.variacion_pct !== null && x.variacion_pct !== undefined && Number(x.variacion_pct) !== 0) {
    const v = Number(x.variacion_pct);
    costo = ` · costo ${x.costo_anterior} → ${x.costo_nuevo} Bs (${v > 0 ? '▲ +' : '▼ '}${v}%)${Math.abs(v) >= 10 ? ' ⚠️' : ''}`;
  }
  return `• ${x.producto}: +${x.cantidad} → stock ${x.stock_nuevo}${costo}`;
});
const faltan = (r.no_encontrados || []).map(x => `• ${x.nombre} (${x.cantidad ?? '?'} a ${x.costo_unitario ?? '?'} Bs)`);

let mensaje = '🧾 Nota de compra registrada\n' + (lineas.join('\n') || '(ningún producto coincidió)');
if (faltan.length) mensaje += '\n\nNo encontré estos en tu lista, cargalos en la app:\n' + faltan.join('\n');
if (lineas.some(l => l.includes('⚠️'))) mensaje += '\n\nOjo: hay costos que cambiaron 10% o más. Revisá tus precios de venta.';

return [{ json: { chat_id: n.telegram_chat_id || '', email: n.email || '', asunto: 'Compra registrada', mensaje } }];
